  PRINT("HELLO FROM X1PEN", /);
END;

DOUBLE(WORD X) BEGIN
  RETURN(X*2);
END;

MAIN() BEGIN
  PRINT(DOUBLE(21), /);
END;

MAIN() BEGIN
  VAR RESULT;
  RESULT=FOPEN(0, "A:DATA.BIN", 0);
  IF RESULT==0 THEN FCLOSE(0);
  PRINT(RESULT, /);
END;

ARRAY BYTE GLYPH[] = {
  $3C,0,0, $7E,0,0, $DB,0,0, $FF,0,0,
  $A5,0,0, $FF,0,0, $66,0,0, $3C,0,0
};

MAIN() BEGIN
  WIDTH(40);
  PCGDEFS(128, GLYPH, 1);
  PRINT(CHR$(128), /);
END;

MAIN() BEGIN
  VAR FLOAT VALUE;
  VALUE=FSQRT(81.0);
  PRINT(FL$(VALUE), /);
END;

MAIN() BEGIN
  PSG_INIT(0);
  PSG_PROC();
  PSG_STOP();
  PSG_END();
END;

MAIN()
{
  VAR OLD, NEW, PRESSED;
  OLD=STICK(0);
  LOOP
  {
    NEW=STICK(0);
    PRESSED=(NEW XOR OLD) AND OLD;
    IF PRESSED!=0 THEN PRINT(HEX2$(PRESSED), /);
    OLD=NEW;
  }
}

ARRAY BYTE M8A_DATA[] = {
  $4D,$38,$41,$00,$01,$01,$49,$49,$49,$49
};

MAIN() BEGIN
  M8ALOAD(M8A_DATA,0,0);
  LOOP VSYNC1();
END;
